# frozen_string_literal: true

RSpec.describe GraphqlTagRbs::Generator do
  it "generates variables, data, and response types for an operation" do
    files = generate(operation(<<~GRAPHQL, file: "app/clients/user_client.rb", line: 4, constant: "Clients::UserClient::USER_QUERY"))
      query UserQuery($id: ID!) {
        user(id: $id) { id name }
      }
    GRAPHQL

    expect(files.keys).to eq(["app/clients/user_client.rbs", "_shared.rbs"])
    expect(files["app/clients/user_client.rbs"]).to eq(<<~RBS)
      # Generated by graphql_tag_rbs from app/clients/user_client.rb. Do not edit.

      module GraphQLTypes
        # query UserQuery at app/clients/user_client.rb:4 (Clients::UserClient::USER_QUERY)
        module UserQuery
          type variables = {
            "id" => ::String | ::Integer
          }

          type data = {
            "user" => {
              "id" => ::String,
              "name" => ::String?
            }?
          }

          type response = {
            ?"data" => data?,
            ?"errors" => ::Array[::GraphQLTypes::error],
            ?"extensions" => ::Hash[::String, untyped]
          }
        end
      end
    RBS
  end

  it "groups definitions by source file, ordered by line" do
    files = generate(
      operation("query B { node(id: 1) { id } }", file: "app/x.rb", line: 9),
      operation("query A { node(id: 1) { id } }", file: "app/x.rb", line: 2),
      operation("query C { node(id: 1) { id } }", file: "lib/y.rb", line: 1)
    )

    expect(files.keys).to eq(["app/x.rbs", "lib/y.rbs", "_shared.rbs"])
    expect(files["app/x.rbs"].index("module A")).to be < files["app/x.rbs"].index("module B")
  end

  it "inlines fragments into operations and generates a data type for each fragment" do
    files = generate(
      operation("query Q { user(id: 1) { ...F role } }"),
      operation("fragment F on User { id createdAt }", line: 5)
    )

    expect(files["app/a.rbs"]).to include(<<~RBS.gsub(/^/, "    "))
      type data = {
        "user" => {
          "id" => ::String,
          "createdAt" => untyped,
          "role" => ::GraphQLTypes::Enums::role
        }?
      }
    RBS
    expect(files["app/a.rbs"]).to include("module F\n    type data = {\n      \"id\" => ::String,")
  end

  it "maps custom scalars from the scalars option" do
    files = generate(operation("query Q { user(id: 1) { createdAt } }"), scalars: { "DateTime" => "::String" })

    expect(files["app/a.rbs"]).to include('"createdAt" => ::String')
  end

  it "makes fields under @include / @skip optional keys, unless also selected unconditionally" do
    files = generate(operation(<<~GRAPHQL))
      query Q($a: Boolean!) {
        user(id: 1) {
          name @include(if: $a)
          id @skip(if: $a)
          id
          ... @include(if: $a) { role }
        }
      }
    GRAPHQL

    expect(files["app/a.rbs"]).to include('?"name" => ::String?,', '"id" => ::String,', '?"role" => ::GraphQLTypes::Enums::role')
  end

  it "uses aliases as keys and merges repeated fields" do
    files = generate(operation("query Q { me: user(id: 1) { id } me: user(id: 1) { name } }"))

    expect(files["app/a.rbs"]).to include(%("me" => {\n        "id" => ::String,\n        "name" => ::String?\n      }?))
  end

  describe "abstract types" do
    it "uses a single record when every possible type selects the same fields" do
      files = generate(operation("query Q { node(id: 1) { __typename id } }"))

      expect(files["app/a.rbs"]).to include(%("node" => {\n        "__typename" => "Bot" | "User",\n        "id" => ::String\n      }?))
    end

    it "uses a union of records tagged by __typename when fields differ" do
      files = generate(operation("query Q { search(term: \"x\") { __typename ... on User { name } } }"))

      expect(files["app/a.rbs"]).to include(%("search" => ::Array[{\n        "__typename" => "Bot"\n      } | {\n        "__typename" => "User",\n        "name" => ::String?\n      }]))
    end

    it "requires __typename when fields differ" do
      expect { generate(operation("query Q { search(term: \"x\") { ... on User { name } } }", line: 3)) }
        .to raise_error(GraphqlTagRbs::Error, /Q \(app\/a\.rb:3\): `search` selects different fields .* Bot, User; select `__typename`/)
    end
  end

  describe "inputs" do
    let(:files) do
      generate(operation(<<~GRAPHQL))
        query Q($filter: UserFilter, $by: UserLookup!, $limit: Int = 5, $ids: [ID!]!) {
          users(filter: $filter) { friends(first: $limit) { id } }
          lookup(by: $by) { id }
          nodes(ids: $ids) { id }
        }
      GRAPHQL
    end

    it "makes nullable variables and variables with defaults optional keys" do
      expect(files["app/a.rbs"]).to include(<<~RBS.gsub(/^/, "    "))
        type variables = {
          ?"filter" => ::GraphQLTypes::Inputs::user_filter?,
          "by" => ::GraphQLTypes::Inputs::user_lookup,
          ?"limit" => ::Integer?,
          "ids" => ::Array[::String | ::Integer]
        }
      RBS
    end

    it "generates referenced input objects, recursively, and enums in the shared file" do
      expect(files["_shared.rbs"]).to include(<<~RBS.gsub(/^/, "    "))
        type user_filter = {
          ?"role" => ::GraphQLTypes::Enums::role?,
          ?"nameContains" => ::String?,
          ?"limit" => ::Integer,
          ?"and" => ::Array[::GraphQLTypes::Inputs::user_filter]?
        }
      RBS
      expect(files["_shared.rbs"]).to include(%(type role = "ADMIN" | "MEMBER"))
    end

    it "generates a union of single-key records for @oneOf input objects" do
      expect(files["_shared.rbs"]).to include(%(type user_lookup = {\n      "id" => ::String | ::Integer\n    } | {\n      "email" => ::String\n    }))
    end
  end

  it "supports symbol keys" do
    files = generate(operation("query Q($id: ID!) { user(id: $id) { id } }"), key_style: "symbol")

    expect(files["app/a.rbs"]).to include("id: ::String | ::Integer", "user: {\n        id: ::String\n      }?", "?data: data?")
    expect(files["_shared.rbs"]).to include("message: ::String", "?extensions: ::Hash[::Symbol, untyped]")
  end

  it "nests modules for a namespace with ::" do
    files = generate(operation("query Q { node(id: 1) { id } }"), namespace: "MyApp::GraphQL")

    expect(files["app/a.rbs"]).to include("module MyApp\n  module GraphQL\n    # query Q")
    expect(files["app/a.rbs"]).to include("::MyApp::GraphQL::error")
  end

  it "capitalizes operation names to make module names" do
    expect(generate(operation("query getUser { node(id: 1) { id } }"))["app/a.rbs"]).to include("module GetUser")
  end

  it "skips unnamed operations with a warning" do
    files = nil
    expect { files = generate(operation("{ node(id: 1) { id } }", line: 7)) }
      .to output(/skipping unnamed operation at app\/a\.rb:7/).to_stderr
    expect(files.keys).to eq(["_shared.rbs"])
  end

  it "reports validation errors with the operation's location" do
    expect { generate(operation("query Q { user(id: 1) { nmae } }", line: 12)) }
      .to raise_error(GraphqlTagRbs::Error, /Q \(app\/a\.rb:12\): Field 'nmae' doesn't exist on type 'User'/)
  end

  it "rejects operation lists from graphql_tag_pluck before 0.3.0" do
    operations = { "Q" => { "name" => "Q", "source" => "query Q { node(id: 1) { id } }", "type" => "query" } }

    expect { described_class.new(schema: fixture_schema, operations: operations) }
      .to raise_error(GraphqlTagRbs::Error, /graphql_tag_pluck 0\.3\.0 or later/)
  end

  it "rejects names that would generate the same module" do
    expect { generate(operation("query getUser { node(id: 1) { id } }"), operation("query GetUser { node(id: 1) { id } }", line: 2)) }
      .to raise_error(GraphqlTagRbs::Error, /both generate module GetUser/)
  end

  it "rejects unknown key styles" do
    expect { generate(key_style: "camel") }.to raise_error(GraphqlTagRbs::Error, /key_style must be one of string, symbol/)
  end
end
